USE luxe_talent;

CREATE TABLE IF NOT EXISTS stripchat_earnings (
    id                          INT AUTO_INCREMENT PRIMARY KEY,
    model_username              VARCHAR(100) NOT NULL,
    performer_email             VARCHAR(255) NULL COMMENT 'FK to registration.email if linked',
    period_type                 VARCHAR(30) NOT NULL DEFAULT 'currentPayment',
    period_start                DATETIME NULL,
    period_end                  DATETIME NULL,
    tips                        INT NOT NULL DEFAULT 0,
    public_chat_tips            INT NOT NULL DEFAULT 0,
    private_chat_tips           INT NOT NULL DEFAULT 0,
    offline_tips                INT NOT NULL DEFAULT 0,
    unlock_chat                 INT NOT NULL DEFAULT 0,
    album_sales                 INT NOT NULL DEFAULT 0,
    video_sales                 INT NOT NULL DEFAULT 0,
    private_shows               INT NOT NULL DEFAULT 0,
    spy_on_privates             INT NOT NULL DEFAULT 0,
    exclusive_privates          INT NOT NULL DEFAULT 0,
    contest_win                 INT NOT NULL DEFAULT 0,
    exclusive_private_no_video  INT NOT NULL DEFAULT 0,
    user_tips_vr                INT NOT NULL DEFAULT 0,
    private_chat_tips_vr        INT NOT NULL DEFAULT 0,
    anonymous_tips              INT NOT NULL DEFAULT 0,
    anonymous_tips_vr           INT NOT NULL DEFAULT 0,
    fan_club_soldiers           INT NOT NULL DEFAULT 0,
    fan_club_lords              INT NOT NULL DEFAULT 0,
    fan_club_princes            INT NOT NULL DEFAULT 0,
    group_shows                 INT NOT NULL DEFAULT 0,
    ticket_show                 INT NOT NULL DEFAULT 0,
    public_tips_vr              INT NOT NULL DEFAULT 0,
    spy_on_privates_vr          INT NOT NULL DEFAULT 0,
    public_show_recordings      INT NOT NULL DEFAULT 0,
    photo_sales_pm              INT NOT NULL DEFAULT 0,
    mass_messages               INT NOT NULL DEFAULT 0,
    models_referral_program     INT NOT NULL DEFAULT 0,
    users_referral_program      INT NOT NULL DEFAULT 0,
    refunds                     INT NOT NULL DEFAULT 0,
    other_income                INT NOT NULL DEFAULT 0,
    total_earnings              INT NOT NULL DEFAULT 0,
    fetched_at                  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_model (model_username),
    INDEX idx_performer (performer_email),
    INDEX idx_period (period_type, period_start),
    INDEX idx_fetched (fetched_at)
) ENGINE=InnoDB;
